import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    pts = set()
    rows = {}
    for i in range(n):
        x, y = int(data[1 + 2 * i]), int(data[2 + 2 * i])
        pts.add((x, y))
        rows.setdefault(y, []).append(x)
    best = -1
    for y, xs in rows.items():
        xs.sort()
        m = len(xs)
        for i in range(m):
            xi = xs[i]
            for j in range(i + 1, m):
                d = xs[j] - xi
                if best != -1 and d >= best:
                    break
                if (xi, y + d) in pts and (xs[j], y + d) in pts:
                    best = d
                    break
    print(best)

